```js
import { spawn } from 'node:child_process';
import { createServer } from 'node:http';
import { readFile, stat } from 'node:fs/promises';
import { extname, join, normalize, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = 'D:/dev/ab-tasks/chessground-qwen-r2';
const PORT = 8123;
const CDP_PORT = 9223;

const MIME = { '.html': 'text/html', '.js': 'text/javascript', '.css': 'text/css', '.map': 'application/json', '.png': 'image/png', '.jpg': 'image/jpeg', '.svg': 'image/svg+xml' };

// --- static server
const server = createServer(async (req, res) => {
  try {
    const url = new URL(req.url, 'http://x');
    let p = decodeURIComponent(url.pathname);
    if (p === '/') p = '/demo.html';
    const file = normalize(join(ROOT, p));
    if (!file.startsWith(ROOT)) { res.writeHead(403); res.end(); return; }
    const data = await readFile(file);
    res.writeHead(200, { 'content-type': MIME[extname(file)] || 'application/octet-stream' });
    res.end(data);
  } catch {
    res.writeHead(404); res.end('not found');
  }
});
await new Promise(r => server.listen(PORT, '127.0.0.1', r));

// --- chrome
const chrome = spawn('/c/Program Files/Google/Chrome/Application/chrome.exe', [
  '--headless=new',
  `--remote-debugging-port=${CDP_PORT}`,
  '--user-data-dir=' + TMPDIR,
  '--no-first-run', '--no-default-browser-check',
  '--disable-gpu',
  'about:blank',
], { stdio: 'ignore' });
```

Wait — the path with spaces: on Windows, spawn with a single-arg exe path is fine (no shell). Use the Windows path `C:\Program Files\Google\Chrome\Application\chrome.exe`.

Also, Chrome may complain about a non-empty user-data-dir or existing profile lock — use a fresh temp directory.

CDP connection:
```js
async function waitForTarget() {
  for (let i = 0; i < 100; i++) {
    try {
      const r = await fetch(`http://127.0.0.1:${CDP_PORT}/json`);
      const list = await r.json();
      const t = list.find(t => t.type === 'page');
      if (t) return t;
    } catch {}
    await new Promise(r => setTimeout(r, 100));
  }
  throw new Error('no CDP target');
}
```

Then navigate:
```js
const ws = new WebSocket(target.webSocketDebuggerUrl);
let id = 0; const pending = new Map(); const events = [];
const exceptions = []; const consoleErrors = [];
function send(method, params = {}) { return new Promise((res, rej) => { const i = ++id; pending.set(i, {res, rej}); ws.send(JSON.stringify({id: i, method, params})); }); }
ws.onmessage = m => { const msg = JSON.parse(m.data);
  if (msg.id) { pending.get(msg.id)?.res(msg.result); pending.delete(msg.id); }
  else { events.push(msg);
    if (msg.method === 'Runtime.exceptionThrown') exceptions.push(msg.params.exceptionDetails);
    if (msg.method === 'Runtime.consoleAPICalled' && msg.params.type === 'error') consoleErrors.push(msg.params.args);
  }
};
await open...
await send('Page.enable'); await send('Runtime.enable');
await send('Page.navigate', { url: `http://127.0.0.1:${PORT}/demo.html` });
// wait for loadEventFired
```

Then poll `Runtime.evaluate` until `document.querySelectorAll('.cg-board').length === 5` or timeout.

